function geoImg182(k,w){const g=GEO182[k];if(!g)return '';return '<figure style="margin:8px 0;max-width:'+(w||100)+'%"><img src="'+g.d+'" alt="'+g.c+'" style="width:100%;border-radius:3px;filter:sepia(.15)"><figcaption style="font-size:12px;opacity:.8;margin-top:2px">'+g.c+' · photographie d’Henri Georgi, vers 1879-1890 (Archives départementales de La Réunion, '+g.cote+')</figcaption></figure>'}
try{if(EV.e1882){const b0=EV.e1882.b;Object.defineProperty(EV.e1882,'b',{get(){return (typeof b0==='string'?b0:'')+geoImg182('10')+geoImg182('11')},configurable:true})}}catch(e){}
Object.assign(EV,{georgi1885:{y:1885,si:()=>S,tag:'Archive',an:'vers 1879-1890',nat:'Fait historique : photographies d’archives.',t:'L’album d’Henri Georgi',
 get b(){return 'Un photographe promène sa chambre noire dans Saint-Denis et le long de la nouvelle voie ferrée. Pour la première fois, l’île se voit telle qu’elle est, en noir et blanc.'+['03','06','08','05','12','15','09','13','20'].map(k=>geoImg182(k)).join('')},
 v:'L’île se regarde.',h:'Archives départementales de La Réunion, albums photographiques d’Henri Georgi (1879-1890), fonds 7 FI 1 : 88 épreuves sur papier albuminé. Images réduites pour le jeu.',o:[{n:'Refermer l’album',d:'',fx:{},hist:1}]}});
Object.assign(EV,{richelieu1862:{y:1862,si:()=>S,tag:'Archive',an:'1862',nat:'Fait historique.',t:'Les 225 du « Richelieu »',
 get b(){return 'À Karikal, sur la côte de l’Inde, 225 engagés indiens montent à bord du « Richelieu », capitaine Avenel, pour La Réunion. Une liste les nomme un par un. Ils viennent remplacer dans les champs de canne les esclaves libérés en 1848. '+(S.voieC?'Sur les habitations, on les loge dans les anciens camps d’esclaves.':'Certains, maltraités, fuiront à leur tour vers les Hauts.')},
 v:'Un nom sur une liste, avant le voyage.',h:'Archives départementales de La Réunion, série M (engagisme et immigration) : « État nominatif des 225 immigrants indiens embarqués à Karikal à bord du navire Le Richelieu, commandé par le capitaine Avenel, à destination de La Réunion », 1862.',o:[{n:'Continuer',d:'',fx:{},hist:1}]}});
